# owner: platform
import unittest
from datetime import date

from rosterkit.errors import ProjectError
from rosterkit.models import Mark, Student
from rosterkit.notices import build_absence_notice

PUPIL = Student("s1", "Lovelace", "Ada", "A")


def mark(day, status="absent", who="s1"):
    return Mark(who, day, status)


class NoticeTests(unittest.TestCase):
    def test_names_count_and_sorted_dates(self):
        marks = [mark(date(2026, 3, 5)), mark(date(2026, 3, 2)), mark(date(2026, 3, 3), "present")]
        text = build_absence_notice(PUPIL, marks)
        self.assertEqual(text, "Ada Lovelace missed 2 days: 2026-03-02, 2026-03-05.")

    def test_single_day(self):
        text = build_absence_notice(PUPIL, [mark(date(2026, 3, 2))])
        self.assertIn("missed 1 day:", text)

    def test_other_student_rejected(self):
        with self.assertRaises(ProjectError):
            build_absence_notice(PUPIL, [mark(date(2026, 3, 2), who="s2")])

    def test_no_absences_rejected(self):
        with self.assertRaises(ProjectError):
            build_absence_notice(PUPIL, [mark(date(2026, 3, 2), "late")])
